static nfs_soft::SurfaceIdentity surface(){nfs_soft::SurfaceIdentity id;id.lifetime=7;auto&g=id.geometry;g[1]=640;g[2]=480;g[5]=640;g[6]=480;g[7]=0x7810;g[8]=0x10000;g[10]=1280;g[11]=0x20000;g[12]=0x30000;g[15]=2;g[16]=1278;g[17]=16;g[18]=1296;g[19]=16+479*1280;return id;}
static std::shared_ptr<const nfs_soft::FontCatalog>font(){nfs_soft::FontDescription description;std::vector<uint8_t>alpha(1024*512);for(unsigned role=0;role<2;++role){description.baseline[role]=2;for(auto&g:description.glyphs[role])g={2,2,8,8,0,-8,3*65536};description.glyphs[role][0]={0,0,0,0,0,0,2*65536};}for(unsigned y=2;y<10;++y)for(unsigned x=2;x<10;++x)alpha[y*1024+x]=128;auto f=nfs_soft::FontCatalog::create(description,alpha.data(),alpha.size(),17);CHECK(f);return f;}
static nfs_soft::TextCommand string(const char*name,int x,int y,int advance,unsigned role,unsigned alignment,unsigned color){nfs_soft::TextCommand c;c.length=unsigned(std::strlen(name));std::memcpy(c.text.data(),name,c.length);c.x=x;c.y=y;c.advance=advance;c.role=role;c.alignment=alignment;c.color=uint16_t(color);c.sourceSize=18;return c;}
