 // Independent measured source order, widths, positions, roles and shadow pairs.
 const char*names[]={"setup","steering sensitivity","force feedback","DONE","CONTROLS"};const int x[]={380,293,320,381,382},y[]={170,196,224,267,105},width[]={36,123,96,35,68};std::vector<nfs_soft::TextCommand>out;
 for(unsigned i=0;i<5;++i){const unsigned color=i==4?3998:i==selected?65535:37904;for(unsigned j=0;j<2;++j)out.push_back(string(names[i],x[i]+(j==0),y[i]+(j==0),width[i],i<3?1:0,i==4?1:2,j==0?1:color));if(i<3)for(unsigned j=0;j<2;++j)out.push_back(string("...",416+(j==0),y[i]+(j==0),12,1,2,j==0?1:color));}return out;
