static Packet packet(const std::vector<nfs_soft::TextCommand>&commands,uint64_t serial=1,int replayFault=0){auto f=font();nfs_soft::FramePacketBuilder b(f);auto id=surface();std::vector<uint16_t>plane(640*480,0x1234);CHECK(b.begin(id,serial,plane.data(),plane.size()));for(unsigned i=0;i<commands.size();++i){CHECK(b.beginString(commands[i]));const uint16_t value=uint16_t(0x8000+i);if(replayFault==1&&i==0){CHECK(!b.word(i,plane[i]^1,value,value));return {};}CHECK(b.word(i,plane[i],value,value));plane[i]=value;CHECK(b.endString(commands[i]));}if(replayFault==2)plane.back()^=1;return b.finish(id,plane.data(),plane.size());}
static void put16(std::array<uint8_t,12>&h,unsigned at,unsigned v){h[at]=uint8_t(v);h[at+1]=uint8_t(v>>8);}
static void put32(std::array<uint8_t,12>&h,unsigned at,uint32_t v){for(unsigned k=0;k<4;++k)h[at+k]=uint8_t(v>>(8*k));}
